  "intro": "DON'T PANIC. You are holding the single most useful guide to the Known Galaxy ever assembled, which is a bold claim for something with no moving parts and a tendency to digress. The galaxy is big. Really big. You just won't believe how vastly, hugely, mind-bogglingly big it is — about 100,000 light-years across, give or take, and stuffed with a few hundred billion stars, most of which have never heard of you and never will. This Guide maps the real ones: real distances, real temperatures, real doomed supergiants. The jokes are free; the facts are load-bearing. Mind the black holes.",
