   "verdict": "A ten-billion-year fusion bomb, kindly distant. Do not approach.",
   "guide": "The local star, and frankly the only reason anyone in this neighbourhood gets out of bed. The Sun is a yellow dwarf of spectral class G2V, which is astronomy's polite way of saying 'utterly average', a description it shares with most of its planets and indeed most of the things that have ever lived on them. It hoards 99.86 percent of the entire system's mass, leaving the planets to squabble over the rounding error. At its core, hydrogen is mashed into helium at around 15 million kelvin, releasing the energy that arrives at your skin a leisurely 8.3 light-minutes later. The light you are presently enjoying left it before you finished this sentence and several times over. It is roughly 4.6 billion years old and has another five billion or so before it swells into a red giant and ruins property values across the inner system.",
