   "name": "Mercury",
   "category": "solar-system",
   "objtype": "Terrestrial planet",
   "verdict": "Smallest planet, worst commute, can't decide on a temperature.",
   "guide": "Mercury is the runt of the planetary litter, smaller than the moons Ganymede and Titan, and has all the atmosphere of a freshly evacuated airlock. What little gas clings to it is a wispy exosphere of atoms knocked loose by the solar wind. Lacking any meaningful blanket, it suffers the most appalling temperature swings in the system: a blistering 430 degrees Celsius where the Sun is overhead and a bone-cracking minus 180 in the dark. It races around the Sun every 88 Earth days, the fastest year going, while turning so sluggishly on its axis that a single solar day lasts two of its years. Despite roasting, it stubbornly hoards water ice in permanently shadowed polar craters, which is precisely the sort of contradiction this system delights in.",
