   "verdict": "Hot enough to melt lead, smells of brimstone, spins backwards.",
   "guide": "Often billed as Earth's twin, which is the kind of cheerful estate-agent language that gets hitchhikers killed. Venus is a cautionary tale wearing a thick veil of cloud. A runaway greenhouse effect has cranked its surface to roughly 465 degrees Celsius, hot enough to melt lead, and held there day and night because the atmosphere is a crushing carbon-dioxide ocean weighing in at about 92 bar, the equivalent of being a kilometre underwater on Earth. The clouds, far from being fluffy, are droplets of sulphuric acid. To complete the perversity, Venus rotates backwards and so slowly that a single day on Venus outlasts its own year. It is the brightest planet in our sky and, viewed from a safe distance, genuinely lovely.",
