   "verdict": "Earth's loyal sidekick; only off-world soil humans have trodden.",
   "guide": "The Moon is Earth's single faithful companion and, to date, the only celestial body other than Earth on which human beings have actually stood about and left footprints, twelve of them having done so between 1969 and 1972. It is tidally locked, meaning it forever shows Earth the same face like a polite dinner guest who refuses to turn away, while the so-called dark side merely faces away from us and gets just as much sunlight. It is slowly leaving, drifting outward at about 3.8 centimetres per year, roughly the rate your fingernails grow, which over billions of years adds up to a long goodbye. Its gravity raises Earth's tides and gently steadies our planet's wobble, making it less a satellite and more an unpaid stabilising consultant.",
