   "objtype": "Terrestrial planet",
   "verdict": "The red one everyone wants to colonise; bring oxygen and patience.",
   "guide": "Mars is the rusty fourth rock, beloved of novelists, billionaires and anyone who finds Earth a touch crowded. It boasts the largest volcano in the solar system, Olympus Mons, which rears some 22 kilometres above the surrounding plains, nearly three times the height of Everest and so broad its base would smother France. The atmosphere is a thin wheeze of carbon dioxide at less than one percent of Earth's pressure, which means liquid water can't survive on the surface and you can't either, not without a suit. Two small lumpy moons, Phobos and Deimos, orbit it like a pair of captured potatoes; Phobos is spiralling inward and will eventually shatter into a ring. Endless dust, sub-zero days and the occasional planet-wide dust storm complete the brochure.",
   "panic": "Don't panic about the colony hype: Mars is genuinely reachable, but the air won't keep you alive and the dust gets into everything. Pack pressurised everything and lower your expectations of WiFi.",
