   "verdict": "The system's heavyweight bouncer with a 350-year-old storm.",
   "guide": "Jupiter is the colossus of the family, a gas giant so vast that all the other planets could be poured inside it with room to spare; it outmasses the rest of them combined by more than double. Its banded face is wracked by a storm, the Great Red Spot, an anticyclone larger than Earth that has been spinning for centuries and was already old when astronomers first reliably noted it. It commands a retinue of 95 or more confirmed moons, a number that keeps creeping upward as fainter ones are spotted, and even wears a faint, dusty ring that nobody noticed until Voyager 1 flew past in 1979. Its monstrous gravity acts as the inner system's bodyguard, flinging away or swallowing comets that might otherwise pester the smaller planets.",
   "panic": "Don't panic: there's no surface to crash onto, which sounds reassuring until you realise that means there's nowhere to land. Its radiation belts will fry unshielded electronics, so admire from a respectful orbit.",
