   "verdict": "The most volcanic place anywhere; a sulphurous pizza in motion.",
   "guide": "Io is the innermost of Jupiter's four big Galilean moons and easily the most overworked body in the solar system. Squeezed mercilessly by Jupiter's gravity on one side and its sibling moons on the other, its interior is kneaded like dough in a process called tidal heating, which keeps it perpetually molten. The result is hundreds of active volcanoes, some hurling plumes of sulphurous material hundreds of kilometres into space, repaving the entire surface so often that Io has essentially no impact craters left. Its mottled yellow, orange and black complexion has earned it the affectionate nickname of a cosmic pizza. It also bathes in Jupiter's lethal radiation and trails a glowing torus of charged particles around the giant. Charming, but not somewhere to picnic.",
