   "verdict": "Ice shell over a hidden ocean; best bet for alien fish.",
   "guide": "Europa is the smoothest large object in the system, an eggshell of water ice cracked across with reddish streaks like a tea-stained marble. Beneath that crust, tidal flexing keeps a global ocean of liquid saltwater sloshing about, holding perhaps twice as much water as all of Earth's oceans combined. Liquid water, a source of heat and the right chemistry make it the most discussed candidate for life beyond Earth, which is why NASA's Europa Clipper launched on 14 October 2024 to investigate, with arrival at Jupiter due around April 2030 followed by nearly fifty close flybys. The catch, as ever, is Jupiter's punishing radiation field, which scours the surface and would do unkind things to any visiting biology, the imported kind especially.",
   "panic": "Don't panic about drilling through the ice; the ocean below may be more hospitable than the surface above. Just shield yourself from Jupiter's radiation, which the ice conveniently does for whatever swims beneath it.",
