   "verdict": "Biggest moon in the system; bigger than Mercury, oddly.",
   "guide": "Ganymede is the heavyweight champion of moons, the largest in the entire solar system and, at 5,268 kilometres across, actually wider than the planet Mercury, though considerably less massive since it's largely ice. It enjoys a distinction no other moon can claim: a self-generated magnetic field, produced by a churning iron core, which carves out its own little magnetic bubble inside Jupiter's far larger one, a magnetosphere within a magnetosphere. It too is thought to harbour a salty ocean buried deep beneath its icy shell. Its surface is a patchwork of ancient dark cratered terrain and younger grooved bright regions, recording a long geological history. The European Space Agency's JUICE mission, launched in 2023, will eventually settle into orbit around it, the first spacecraft ever to orbit a moon other than our own.",
