   "objtype": "Moon of Saturn",
   "verdict": "Has weather, lakes and rivers; just not the water kind.",
   "guide": "Titan, Saturn's largest moon, is the only moon in the solar system with a proper thick atmosphere, a hazy orange nitrogen shroud denser even than Earth's, with surface pressure about 1.5 times ours. Beneath the smog lies the only other world known to have stable liquid on its surface, though the rivers, rain and seas are not water but liquid methane and ethane, sloshing about at a frigid minus 179 degrees Celsius. It has a full hydrological cycle, just running on hydrocarbons instead of water, which makes it the eeriest familiar landscape in the system. The European Huygens probe parachuted onto its surface on 14 January 2005, the most distant landing humanity has ever achieved, sending back glimpses of pebble-strewn ground that looked unsettlingly like a damp riverbed.",
