   "verdict": "Tiny, blinding-white, and quietly spitting ocean into space.",
   "guide": "Enceladus is a small, dazzlingly white moon of Saturn, only about 504 kilometres across, that punches absurdly above its weight in the search for life. From great fissures near its south pole, dubbed the tiger stripes, towering plumes of water vapour and ice grains erupt continuously into space, fed by a global subsurface ocean of liquid saltwater. The Cassini spacecraft flew directly through these geysers and tasted them, detecting salts, organic molecules and even molecular hydrogen, a tidy chemical menu for microbes. So much material is flung out that it replenishes Saturn's faint, diffuse E ring. Its surface reflects almost all the sunlight that strikes it, making it one of the most reflective bodies known and, fittingly, one of the coldest.",
