   "verdict": "The showpiece. Magnificent rings; would float in a big enough bath.",
   "guide": "Saturn is the planet everyone draws when asked to draw a planet, on account of its glorious ring system, a vast disc of countless ice and rock particles spanning hundreds of thousands of kilometres yet often only tens of metres thick, a piece of celestial showmanship the other gas giants can only envy with their feeble dusty bands. It is the least dense planet in the system, less dense than water, so the old party trick holds: given an implausibly large enough bathtub, Saturn would float. At its north pole sits a bizarre and persistent six-sided jet stream, the famous hexagon, wide enough to swallow several Earths, whose tidy geometry continues to puzzle meteorologists. It hosts a great flock of moons, including the remarkable Titan and Enceladus.",
