   "category": "solar-system",
   "objtype": "Ice giant",
   "verdict": "Tipped on its side; coldest atmosphere; rolls around the Sun.",
   "guide": "Uranus is the system's eccentric, an ice giant that lies almost entirely on its side, tilted a preposterous 98 degrees, very likely the legacy of an ancient colossal collision. This means it effectively rolls around its orbit like a dropped marble, with each pole spending roughly 42 years in continuous sunlight followed by 42 years of darkness. It holds the record for the coldest planetary atmosphere measured anywhere, with cloud-top temperatures dipping to around minus 224 degrees Celsius, colder even than distant Neptune, which has no business being warmer but is. Its serene blue-green hue comes from methane in the upper atmosphere absorbing red light. It too has a set of dark, narrow rings and a clutch of moons named, unusually, after Shakespearean and Popean characters. Only Voyager 2 has ever visited, briefly, in 1986.",
   "panic": "Don't panic about the tilt; gravity won't notice you're lying sideways relative to its orbit. Do bring extraordinary insulation, as this is the chilliest planetary air in the system.",
