   "id": "neptune",
   "name": "Neptune",
   "category": "solar-system",
   "objtype": "Ice giant",
   "verdict": "Windiest world, deepest blue, discovered by pure arithmetic.",
   "guide": "Neptune is the outermost of the major planets and, satisfyingly, the only one discovered with a pencil before a telescope. Astronomers noticed Uranus wasn't keeping to its predicted orbit, did the sums on where an unseen tugging planet must be, and on 23 September 1846 there it was, almost exactly where mathematics had promised. It is a deep, vivid blue, partly from methane and partly from some not-fully-explained extra ingredient, and it harbours the fiercest winds in the solar system, supersonic gales tearing along at up to 2,100 kilometres per hour. So distant that sunlight is a thousandfold feebler than at Earth, it nonetheless drives a violently active atmosphere. A single Neptunian year lasts about 165 Earth years, so it has completed barely one full orbit since its discovery. Voyager 2 remains its only visitor, in 1989.",
   "panic": "Don't panic about getting lost out here; just remember it's a four-hour radio round-trip to ask for directions. Hold onto your hat, the winds are the fastest known anywhere.",
