   "objtype": "Moon of Neptune",
   "verdict": "Orbits the wrong way; a stolen Kuiper world spitting nitrogen.",
   "guide": "Triton is Neptune's largest moon and the system's great rebel: it orbits backwards, against its planet's spin, the only large moon to do so. This retrograde path is the tell-tale sign that Triton was not born around Neptune at all but is a captured Kuiper Belt object, an icy interloper press-ganged into service and now slowly spiralling to its doom; in some far future it will be torn apart into a ring. Despite a surface temperature of around minus 235 degrees Celsius, near the coldest measured in the solar system, it is geologically alive: Voyager 2 in 1989 spotted geysers venting nitrogen gas and dark dust kilometres into its thin nitrogen atmosphere. Its cantaloupe-textured terrain and fresh, barely-cratered surface betray ongoing resurfacing on a world that ought, by rights, to be frozen stiff.",
