   "category": "solar-system",
   "objtype": "Dwarf planet",
   "verdict": "Demoted but defiant; sports an enormous nitrogen-ice heart.",
   "guide": "Pluto is the solar system's most famous administrative casualty, reclassified from ninth planet to dwarf planet in 2006, a decision that still inspires letters of complaint. Discovered in 1930 by Clyde Tombaugh, it spent most of a human lifetime as a mere smudge until NASA's New Horizons probe screamed past on 14 July 2015 and revealed an astonishingly complex little world. Its most striking feature is Tombaugh Regio, a vast heart-shaped plain whose western lobe, Sputnik Planitia, is a glacier of nitrogen ice hundreds of kilometres across that actively churns and convects, repaving itself. It has a thin nitrogen atmosphere, towering water-ice mountains and five known moons, the largest of which, Charon, is so big the two effectively waltz around a point in empty space between them. Out here a single year lasts 248 Earth years.",
