   "objtype": "Dwarf planet",
   "verdict": "Belt's biggest resident; a dwarf planet wearing salt spots.",
   "guide": "Ceres is the largest object in the asteroid belt and, by a quirk of classification, also a dwarf planet, holding both titles simultaneously like a knight who is also a postman. At about 940 kilometres across it accounts for roughly a quarter of the entire belt's mass, which says more about how sparse the belt is than how large Ceres is. When the Dawn spacecraft orbited it from 2015, it found mysterious bright spots in Occator Crater that turned out to be deposits of sodium carbonate and other salts, the residue of briny water that welled up from below and evaporated, hinting at a remnant subsurface ocean or muddy layer. Discovered in 1801, it was actually hailed as a new planet for half a century before the rest of the belt was found and it was reclassified, the original demotion long before Pluto's.",
