   "name": "Proxima Centauri",
   "category": "nearby-star",
   "objtype": "M5.5Ve red dwarf flare star",
   "verdict": "The nearest sun, and it positively spits at you.",
   "guide": "At 4.247 light-years, Proxima is the closest star to our own, which makes it the default first stop for any hitchhiker who has misplaced their towel near Sol. Do not be fooled by its proximity into thinking it friendly. It is a piddling M5.5Ve red dwarf of barely 0.12 solar masses and a surface around 3,000 K, so dim (apparent magnitude 11.13) you cannot see it without a telescope despite it being right next door. It is also a notorious flare star, hurling out X-ray and UV tantrums that would sterilise anything optimistic enough to be standing nearby. And yet it has planets: Proxima b, an Earth-mass world in the habitable zone discovered in 2016, plus candidate Proxima c. It is gravitationally bound to the Alpha Centauri pair, orbiting them every ~550,000 years, which is a very long time to wait for the bus.",
   "panic": "Don't panic, but pack serious radiation shielding and time your sightseeing between flares. Proxima b sits in the habitable zone, so aim there, not at the star.",
