   "name": "Alpha Centauri A",
   "category": "nearby-star",
   "objtype": "G2V main-sequence star",
   "verdict": "Practically the Sun's twin, only marginally more pleased with itself.",
   "guide": "If you want to feel at home while being terribly far from it, Alpha Centauri A is your destination. At 4.37 light-years it is a G2V star, the very same spectral classification as our own Sun, only slightly larger and brighter (about 1.1 solar masses and 1.5 times the Sun's luminosity). It is the brightest component of the Alpha Centauri triple system and, combined with its companion B, forms the third-brightest point of light in Earth's night sky. The two stars orbit each other every ~79.9 years in a comfortably elliptical waltz. It is so reassuringly Sun-like that science fiction has been emigrating there for decades, though as of now no confirmed planets orbit A itself, merely tantalising hints. A genuinely civilised place to break a long journey.",
