   "name": "Alpha Centauri B",
   "category": "nearby-star",
   "objtype": "K1V orange dwarf",
   "verdict": "The Sun's slightly smaller, slightly orange understudy.",
   "guide": "Alpha Centauri B is the second member of the famous triple, a K1V orange dwarf sitting at the same 4.37 light-years as its brighter sibling A. At about 0.9 solar masses and roughly half the Sun's luminosity, it is the cooler, dimmer, more frugal of the pair, with a surface temperature near 5,260 K giving it a faintly amber cast. The two orbit a common centre every ~79.9 years, swinging between 11 and 36 astronomical units apart, so a hitchhiker could in principle commute between A and B on a leisurely interplanetary cruise. K-type stars like B are increasingly fashionable among habitability theorists: long-lived, stable, and gentle, the sensible choice for a civilisation that intends to stick around. A 2021 candidate planet, 'C1', remains unconfirmed.",
