   "id": "wolf-359",
   "name": "Wolf 359",
   "category": "nearby-star",
   "objtype": "M6 red dwarf flare star",
   "verdict": "A tiny, twitchy ember; impressive only by being so near.",
   "guide": "Wolf 359, 7.86 light-years off in the constellation Leo, is one of the lowest-mass and faintest stars known anywhere near us, a feeble M6 red dwarf of roughly 0.09 solar masses, barely above the boundary where a star gives up and becomes a brown dwarf. Its surface simmers at only ~2,800 K and its absolute magnitude is so dim that, despite being practically a neighbour, it shines at apparent magnitude 13.5, utterly invisible to the unaided eye. What it lacks in dignity it makes up in temper: it is an active flare star, prone to sudden brightenings, and emits X-rays. Catalogued by Max Wolf in 1918 from its proper motion. Two candidate planets have been proposed but remain unconfirmed. Science-fiction fans may recognise the name from a certain televised space battle; the real star is rather quieter.",
   "panic": "Don't panic: it's small but flares without warning, so monitor for outbursts. There's little to land on here, treat it as a brief, well-shielded pit stop.",
