   "name": "Lalande 21185",
   "category": "nearby-star",
   "objtype": "M2 red dwarf",
   "verdict": "The brightest red dwarf in the northern sky, still invisible to you.",
   "guide": "Lalande 21185 sits 8.31 light-years away in Ursa Major, making it the nearest star in that constellation and, despite being a dim M2 red dwarf, one of the brightest red dwarfs in Earth's northern sky at apparent magnitude 7.5, still just below naked-eye visibility. It carries about 0.39 solar masses and a surface near 3,600 K. Named for the catalogue of Joseph Jérôme de Lalande (1801), it has a notable proper motion and is drifting toward us, due to make its closest approach in around 20,000 years. Like Barnard's Star it suffered decades of unconfirmed planet rumours; modern precision finally delivered, with at least one or two planets now reported, including a candidate gas-giant-mass companion on a multi-year orbit. A respectable, well-behaved sort of star for a layover.",
