   "objtype": "A1V main-sequence star",
   "verdict": "The brightest star in the night sky, and it knows it.",
   "guide": "Sirius A, the Dog Star, is the most dazzling star in Earth's entire night sky at apparent magnitude -1.46, which it achieves partly by being genuinely luminous (about 25 times the Sun) and partly by being a mere 8.6 light-years away. It is an A1V main-sequence star of roughly 2 solar masses with a hot ~9,940 K surface, giving it that crisp blue-white glare so beloved of ancient Egyptians, who timed their calendar to its heliacal rising. It is also the brightest jewel of the constellation Canis Major. What casual observers miss is that Sirius is double: it has a tiny, dense white-dwarf companion, Sirius B, deduced from wobbles by Bessel in 1844 and first glimpsed in 1862. A brilliant, hot, slightly arrogant beacon.",
