   "id": "sirius-b",
   "name": "Sirius B",
   "category": "nearby-star",
   "objtype": "DA white dwarf",
   "verdict": "A whole Sun crammed into an Earth; mind the gravity.",
   "guide": "Sirius B, nicknamed 'the Pup', is the dead-star companion to brilliant Sirius A, sharing its 8.6-light-year distance. It is a white dwarf: the burnt-out core of a once larger star, now packing roughly one solar mass into a sphere about the size of Earth. That makes its surface gravity staggering, around 100,000 times Earth's, and its density almost incomprehensible, a teaspoonful weighing tonnes. Despite being a corpse it remains hot, with a surface near 25,000 K, hotter than its living companion, though so small it shines feebly at magnitude 8.4. Its existence was inferred by Bessel from Sirius A's wobble in 1844 and confirmed visually by Alvan Graham Clark in 1862. The two orbit each other every ~50 years. A landmark in stellar physics, and an excellent reminder of where stars eventually go.",
