   "objtype": "M-dwarf flare binary",
   "verdict": "A pair of twitchy red dwarves that double in brightness when annoyed.",
   "guide": "Luyten 726-8, lying 8.73 light-years away in Cetus, is a binary of two very low-mass red dwarfs, each around an M5-M6 type and roughly 0.1 solar masses, orbiting each other every ~26.5 years. Its claim to fame is the secondary component, UV Ceti, the prototype of the 'UV Ceti-type' flare stars: a star so prone to violent outbursts that it can brighten several-fold in mere seconds before subsiding. Both stars are flare-active, making this one of the more dramatic addresses in the neighbourhood. Discovered by Willem Luyten in 1948 from its large proper motion, the system is otherwise faint and unremarkable to look at, hovering around magnitude 12, until one of the pair throws a tantrum and momentarily lights up. Bring eye protection and don't take it personally.",
