   "objtype": "M3.5 red dwarf flare star",
   "verdict": "The nearest star in Sagittarius, and a restless little flarer.",
   "guide": "Ross 154 is a red dwarf 9.7 light-years away in Sagittarius, the closest star to us in that constellation. It is an M3.5 dwarf of about 0.17 solar masses with a surface near 3,300 K, shining at apparent magnitude 10.4, well below naked-eye reach. Like so many of its red-dwarf cousins it is a flare star, capable of abrupt brightenings, and it is also a comparatively young one by red-dwarf standards, perhaps under a billion years old, which partly explains its energetic temperament. It was catalogued by Frank Elmore Ross in 1925, one of several nearby high-proper-motion stars that bear his name. No planets have been confirmed. A pleasantly nondescript star whose chief distinction is simply being close, and occasionally cross.",
