   "name": "Ross 248",
   "category": "nearby-star",
   "objtype": "M5 red dwarf",
   "verdict": "In 36,000 years it'll be our nearest star; book early.",
   "guide": "Ross 248, currently 10.3 light-years away in Andromeda, is an unassuming M5 red dwarf of roughly 0.14 solar masses and a cool ~3,000 K surface, faint at magnitude 12.3. Its distinction is entirely a matter of timing: it is moving toward the Solar System fast enough that in about 36,000 years it will briefly overtake Proxima Centauri to become the closest star to the Sun, at perhaps 3.0 light-years, before continuing on its way. Catalogued by Frank Ross in 1926, it is also a mild flare star. Voyager 2, having left the Solar System, is loosely headed in roughly its direction and will pass within a couple of light-years of it in some 40,000 years, which is the sort of long-range scheduling that makes interstellar travel feel almost relaxing. No confirmed planets, but an excellent star to keep on retainer.",
