   "category": "nearby-star",
   "objtype": "K2V young dwarf",
   "verdict": "A youthful Sun-ish star wreathed in debris; a builder's yard.",
   "guide": "Epsilon Eridani, 10.5 light-years away in the river-constellation Eridanus, is one of the nearest Sun-like stars you can actually see with the naked eye (magnitude 3.7). It is a K2V orange dwarf, around 0.82 solar masses and a youthful 400-800 million years old, which makes it magnetically active and rather blotchy with starspots. Its real allure is the debris: it harbours at least one prominent dusty disk and possibly rings of icy material, a solar system caught mid-construction. A giant planet, Epsilon Eridani b, with roughly the mass of Jupiter, was reported orbiting it, long debated but increasingly supported. Frank Drake aimed Project Ozma's first SETI search here in 1960, so it has been on humanity's call list for a very long time. A promising, if dusty, neighbourhood.",
