   "id": "61-cygni",
   "name": "61 Cygni",
   "category": "nearby-star",
   "objtype": "K-dwarf binary",
   "verdict": "The 'Flying Star' whose distance humanity measured first.",
   "guide": "61 Cygni, 11.4 light-years away in Cygnus, earns its place in history as the first star ever to have its distance measured by parallax, by Friedrich Bessel in 1838, the moment Earth finally got a tape measure long enough for the stars. It is a binary of two orange K-type dwarfs, 61 Cygni A (K5V, ~0.7 solar masses) and 61 Cygni B (K7V, ~0.63 solar masses), orbiting each other over a leisurely ~659 years. The pair share a famously large proper motion, earning the nickname 'Flying Star' from Giuseppe Piazzi, who spotted its motion around 1804. Both are visible to a keen naked eye under dark skies at around magnitude 5. Long-rumoured planets here have never been confirmed, but as the star that anchored the entire cosmic distance ladder, 61 Cygni deserves a respectful salute.",
   "panic": "Don't panic: this is a stable, ancient pair, among the safest stops around. With two stars, just plot your trajectory to avoid an unplanned slingshot.",
