   "verdict": "The Little Dog's bright star, quietly outgrowing its youth.",
   "guide": "Procyon A, 11.46 light-years away in Canis Minor, is the eighth-brightest star in Earth's night sky at apparent magnitude 0.34, a brilliance owed both to genuine luminosity (about 7 times the Sun) and to its proximity. It is an F5IV-V star of roughly 1.5 solar masses and a ~6,530 K surface, now beginning to evolve off the main sequence into a subgiant as it exhausts its core hydrogen, an early hint of stellar middle age. Like Sirius, Procyon is double: it has a faint white-dwarf companion, Procyon B, inferred from its wobble in 1844 and finally seen in 1896, the two orbiting every ~40.8 years. It forms one corner of the Winter Triangle alongside Sirius and Betelgeuse. A bright, dependable landmark for navigation across the local sky.",
