   "category": "nearby-star",
   "objtype": "G8V Sun-like star",
   "verdict": "The nearest lone Sun-twin; understandably crowded with hopefuls.",
   "guide": "Tau Ceti, 11.9 light-years away in Cetus, is the nearest single Sun-like star, a G8V dwarf of about 0.78 solar masses that, unlike chummy Alpha Centauri, sails through space alone. At magnitude 3.5 it is easily naked-eye visible, and it is metal-poor and old, perhaps 8-10 billion years, a steady veteran. It has long been a favourite of planet-hunters and SETI alike: it was one of Frank Drake's two original Project Ozma targets in 1960. Several candidate planets have been proposed from delicate radial-velocity signals, including possible Tau Ceti e and f near or in the habitable zone, though confirmation is notoriously difficult amid the star's noise. It also hosts a substantial debris disk with far more cometary material than our own. Long the spiritual home of fictional colonists, it remains a genuinely tantalising real-world target.",
