   "name": "Epsilon Indi",
   "category": "nearby-star",
   "objtype": "K5V orange dwarf",
   "verdict": "An orange dwarf chaperoning a pair of failed stars.",
   "guide": "Epsilon Indi, 11.9 light-years away in the southern constellation Indus, is a K5V orange dwarf of about 0.76 solar masses, a brisk-moving and fairly old star visible to the naked eye at magnitude 4.7. Its great curiosity lies in its companions: roughly 1,460 astronomical units away orbits a pair of brown dwarfs, Epsilon Indi Ba and Bb, sub-stellar objects too lightweight to ignite proper hydrogen fusion, discovered in 2003. These 'failed stars' make the system a natural laboratory for studying the murky boundary between planets and stars. A giant planet, Epsilon Indi Ab, of several Jupiter masses on a wide, long-period orbit, was reported and directly imaged with JWST in 2024. Between a stable orange sun, a brown-dwarf double, and a confirmed gas giant, this is a remarkably varied stop.",
