   "verdict": "A quiet dwarf with a temperate world, and Procyon for a neighbour.",
   "guide": "Luyten's Star, 12.36 light-years away in Canis Minor, is an M3.5 red dwarf of about 0.26 solar masses and a ~3,150 K surface, shining feebly at magnitude 9.9. It was catalogued by the indefatigable Willem Luyten, who spent decades hunting high-proper-motion stars, and it indeed has a notable proper motion of its own. Its appeal is planetary: Luyten's Star b (GJ 273 b), announced in 2017, is a roughly 2.9-Earth-mass world orbiting within the habitable zone, making it one of the better nearby candidates for temperate conditions. By a pleasant coincidence it lies only about 1.2 light-years from brilliant Procyon, so a hitchhiker could pair the two into a single sightseeing excursion. In 2017 a deliberate interstellar radio message, 'Sonar Calling', was beamed here, so the locals, if any, have been put on notice.",
