   "guide": "Teegarden's Star, 12.5 light-years away in Aries, is an ultra-cool M7 red dwarf, one of the smallest and faintest stars near us, with only about 0.08 solar masses, a frigid ~2,900 K surface, and a dismal apparent magnitude of 15, so dim it was only discovered in 2003, in archival asteroid-survey data rather than by any deliberate hunt. It is also extremely old, possibly around 8 billion years, and reassuringly inactive. Despite its modesty it punches above its weight: in 2019 astronomers announced at least two planets, Teegarden's Star b and c, both close to one Earth mass and both orbiting in or near the habitable zone, among the most Earth-like nearby worlds by mass yet found. For a star you can barely see, that is a remarkable haul.",
