   "verdict": "An ancient halo wanderer racing backwards through the Galaxy.",
   "guide": "Kapteyn's Star, 12.8 light-years away in the southern constellation Pictor, is no ordinary neighbour but a visitor from the Galaxy's halo, an ancient, metal-poor M1 subdwarf likely around 11-12 billion years old, nearly as old as the Universe itself. It carries about 0.28 solar masses and is famous for its extreme velocity: it orbits the Milky Way retrograde, moving backwards relative to most local stars, and shows the second-largest proper motion of any star (after Barnard's). Jacobus Kapteyn catalogued this dash in 1898. It may have originated in a dwarf galaxy long ago shredded and absorbed by the Milky Way, possibly the progenitor of the Omega Centauri cluster. Two candidate planets reported in 2014 were later disputed and are now doubtful. A grizzled, fast-moving relic from the deep past, just passing through.",
