   "category": "famous-star",
   "objtype": "Red supergiant",
   "verdict": "A doomed giant, currently rehearsing its own explosion. Mostly patient.",
   "guide": "Betelgeuse, the ruddy left shoulder of Orion, is a red supergiant roughly 700 times the Sun's radius and around 16 solar masses, sitting some 548 light-years off. It is the sort of star that, if dropped where the Sun is, would swallow Mercury, Venus, Earth and Mars without noticing. In late 2019 it stunned astronomers with the Great Dimming, fading to magnitude ~1.6 by February 2020 - the faintest in two centuries - before recovering. The culprit was a vast belch of gas that cooled into a dust cloud, briefly veiling the star, not, disappointingly, the beetlejuice of a certain film. It will eventually go supernova, though 'eventually' here means anytime within the next 100,000 years. Surface temperature is a comparatively chilly 3,600 K.",
