   "name": "Rigel",
   "category": "famous-star",
   "objtype": "Blue supergiant",
   "verdict": "Orion's blazing blue foot. Outshines the Sun 120,000-fold.",
   "guide": "Rigel is the brilliant blue-white supergiant marking Orion's left foot, and despite carrying the 'beta' label it is reliably the brightest star in the constellation - Betelgeuse only occasionally cheats its way ahead during outbursts. Lying about 860 light-years away, Rigel is a B8 Ia supergiant blazing with roughly 120,000 times the Sun's luminosity from a surface near 12,000 K. It is around 21 solar masses and some 79 times the Sun's radius, which is enormous by any sane standard yet positively dainty next to the red hypergiants. Rigel is itself a multiple system, with at least one fainter companion that is itself a close binary. Like Betelgeuse, it is fated to end as a supernova, being too massive to retire quietly into a white dwarf.",
