   "id": "vega",
   "name": "Vega",
   "category": "famous-star",
   "objtype": "A0V main-sequence star",
   "verdict": "The original standard candle. Was the pole star, will be again.",
   "guide": "Vega, in Lyra the Lyre, is a crisp blue-white A0 V dwarf just 25 light-years away, which makes it practically a neighbour. For much of the twentieth century it served as the zero-point of the magnitude scale - by definition, Vega was 'magnitude 0' and everything else was measured against it. Around 12,000 BC it was Earth's pole star, and thanks to the 26,000-year wobble of axial precession it will be again around AD 13,700. Vega spins ferociously, flattening itself noticeably, and is encircled by a dusty debris disk. It is roughly twice the Sun's mass, about 40 times its luminosity, with a surface near 9,600 K. It also starred, fictionally, as the source of the signal in Carl Sagan's Contact.",
   "panic": "DON'T PANIC: should you receive a mysterious prime-number broadcast from this direction, it is almost certainly terrestrial interference. Vega is a calm, well-behaved star and an excellent backup North Star.",
