   "category": "famous-star",
   "objtype": "Cepheid variable supergiant",
   "verdict": "The current North Star. Conveniently parked above the pole.",
   "guide": "Polaris, the present-day North Star, has the enormously useful property of sitting within about three-quarters of a degree of the celestial north pole, so it barely budges as the sky wheels overhead - making it humanity's favourite navigational fixed point. It is not, however, a humble star: Polaris is a yellow supergiant about 430 light-years away, around 5.4 solar masses and several thousand times the Sun's luminosity. It is also a Cepheid variable, gently pulsing with a period of just under four days, and the brightest Cepheid in the sky. It anchors a multiple system with at least one close companion and a wider one. Owing to precession, Polaris is only temporarily on duty; it will be at its closest to true north around AD 2100.",
   "panic": "DON'T PANIC if you're lost in the northern hemisphere: find Polaris and you face north. Its altitude in degrees equals your latitude. In the southern hemisphere, you're on your own - sorry.",
