   "verdict": "The glaring orange eye of the Bull. Not actually in the Hyades.",
   "guide": "Aldebaran is the fiery orange eye of Taurus the Bull, an evolved K5 III giant about 65 light-years away. It appears to sit among the V-shaped Hyades cluster, but this is a celestial coincidence - Aldebaran is a foreground star roughly half the distance to that cluster, merely photobombing the arrangement. Having exhausted its core hydrogen, it has swollen to about 44 times the Sun's radius while cooling to a sullen 3,900 K, shining with around 400 solar luminosities. Its name comes from the Arabic for 'the follower', because it trails the Pleiades across the sky. The Pioneer 10 probe is, very loosely, headed in its general direction, due to arrive in roughly two million years - assuming Aldebaran waits politely where it is.",
