   "objtype": "Red supergiant",
   "verdict": "The blood-red heart of the Scorpion. A rival to Mars.",
   "guide": "Antares is the brooding red heart of Scorpius, a red supergiant roughly 550 light-years distant. Its very name means 'rival of Ares' (Mars), because its ruddy glow so closely matches the Red Planet that the two are easily confused when they pass near one another. It is a true giant - around 680 times the Sun's radius and some 12 solar masses, cool at about 3,600 K yet luminous enough to outshine the Sun tens of thousands of times. Plonked in the Solar System, its surface would extend out past the orbit of Mars. Antares has a hot blue companion star, Antares B, that is normally lost in its overwhelming glare. Like all such bloated supergiants, it is destined to detonate as a supernova in astronomically short order.",
   "panic": "DON'T PANIC if you mistake it for Mars - so has nearly everyone for three thousand years. Antares twinkles and Mars doesn't; that's your tell. Its future supernova is far too distant to fret over.",
