   "verdict": "Fourth-brightest star, barrelling through the galaxy sideways.",
   "guide": "Arcturus, the leading light of Booetes the Herdsman, is the fourth-brightest star in the night sky and the brightest in the northern celestial hemisphere. At a comfortable 36.7 light-years it is an orange K-type giant, roughly 25 times the Sun's radius and about 170 times its luminosity, with a temperature near 4,300 K. What makes Arcturus a celebrity among kinematicists is its breakneck motion: it belongs to a stream of stars hurtling through the galactic disk at high speed relative to the Sun, and it carries one of the largest proper motions of any bright star. In a few thousand years it will have visibly shifted position. To find it, simply 'arc to Arcturus' by following the curve of the Big Dipper's handle.",
