   "guide": "Spica, the brightest star in Virgo and traditionally the ear of wheat held by the maiden, looks like a single brilliant blue point but is in fact a tight binary of two hot B-type stars. They orbit a shared centre of gravity every four days at such close quarters that mutual gravity has stretched them into egg shapes - a rotating ellipsoidal variable. The primary is around 11 solar masses and ferociously hot, near 22,000 K, easily energetic enough to end its life as a supernova. The pair lie roughly 250 light-years away. To locate Spica, continue the arc from the Big Dipper past Arcturus and 'spike to Spica'. Its blue-white colour betrays surface temperatures far above the Sun's mellow yellow.",
