   "category": "famous-star",
   "objtype": "Blue-white supergiant",
   "verdict": "Absurdly luminous, absurdly far. Still one of our brightest.",
   "guide": "Deneb marks the tail of Cygnus the Swan and the top of the Summer Triangle, and it holds a special distinction: it is one of the most intrinsically luminous stars visible to the naked eye. The catch is its distance - roughly 2,600 light-years, far enough that most stars would vanish entirely. To appear so bright across that gulf, Deneb must blaze with something on the order of 100,000-200,000 times the Sun's luminosity. It is an A2 Ia blue-white supergiant of around 19 solar masses and perhaps 200 times the Sun's radius, with a surface near 8,500 K. It is shedding mass through a powerful stellar wind and, inevitably for such a heavyweight, is bound for a supernova ending. The other Summer Triangle stars, Vega and Altair, are practically next door by comparison.",
   "panic": "DON'T PANIC about the staggering distance - that's precisely why Deneb is harmless. Use the Summer Triangle (Deneb, Vega, Altair) to orient yourself on warm evenings; Deneb is the faintest-looking but most powerful of the three.",
