   "name": "Altair",
   "category": "famous-star",
   "objtype": "A-type main-sequence star",
   "verdict": "Spinning so fast it's gone visibly squashed. Charmingly nearby.",
   "guide": "Altair, the brightest star in Aquila the Eagle and the southern apex of the Summer Triangle, is an unassuming-looking white A7 star just 16.7 light-years away - one of the closest naked-eye stars. Its party trick is rotation: Altair spins so rapidly, completing a turn in roughly nine hours, that centrifugal force has flung its equator outward, leaving it measurably oblate. Interferometers have actually imaged this flattening, making it one of the few stars whose shape we can see is not round; the equatorial diameter is about 20 percent larger than the polar. It is around 1.8 solar masses, some 10 times the Sun's luminosity, with a surface around 7,500 K and equatorial regions cooler than the poles thanks to gravity darkening.",
   "panic": "DON'T PANIC about a star spinning near its breakup speed - Altair is stable and a friendly 16.7 light-years off. Find the Summer Triangle and Altair is the lowest, swiftest-turning corner.",
