   "objtype": "Yellow giant binary",
   "verdict": "Two yellow giants masquerading as one bright golden star.",
   "guide": "Capella, the brightest star in Auriga the Charioteer and sixth-brightest in the whole sky, looks like a single golden point but is really a close pair of yellow giant stars orbiting each other every 104 days. Both are more massive than the Sun - roughly 2.5 and 2.6 solar masses - and have swollen off the main sequence into giants, which is why the system shines with around 80 times the combined luminosity of the Sun. The pair lie a neighbourly 42.9 light-years away. Curiously, both giants are similar in temperature to the Sun (one is yellower, around 4,900 K, the other hotter near 5,700 K), so Capella's overall colour is a warm gold. A second, fainter pair of red dwarfs orbits the bright duo at great distance, making this a quadruple system.",
