   "verdict": "The lonely autumn star, ringed by a sharp-edged dust belt.",
   "guide": "Fomalhaut, the brightest star in Piscis Austrinus (the Southern Fish), is often nicknamed the Lonely Star or the Solitary One because it shines in a sparse patch of the southern autumn sky with no bright companions nearby. It is a young, white A-class star about 25 light-years away, roughly 1.9 solar masses and around 16 times the Sun's luminosity. Its real fame comes from its spectacular debris disk: a sharply defined ring of dust and ice imaged by Hubble, marking a young planetary system in the making. An object once heralded as the planet Fomalhaut b later appeared to be an expanding cloud of debris from a collision rather than a world - a cautionary tale in exoplanet hunting. The system also includes two widely separated stellar companions.",
