   "guide": "Regulus, whose name means 'little king', is the brightest star in Leo and marks the heart of the Lion, sitting near the base of the backwards-question-mark asterism known as the Sickle. It lies about 79 light-years away and is a hot blue-white B-type star roughly 3.8 solar masses and several hundred times the Sun's luminosity. Like Altair it is a furious rotator - whirling around in under a day, close to the speed at which it would tear itself apart - so it too is visibly flattened into an oblate spheroid, with its poles hotter than its bulging equator. Regulus is the brightest member of a multiple system that includes a likely white-dwarf companion in a close 40-day orbit, plus a more distant pair. It sits almost exactly on the ecliptic, so the Moon and planets regularly glide past it.",
