   "guide": "Pollux is the brighter of the Gemini twins (outshining its 'twin' Castor despite the beta designation) and holds the distinction of being the closest giant star to the Sun, at about 34 light-years. It is an evolved orange K0 III giant, roughly twice the Sun's mass and around nine times its radius, glowing with some 40 solar luminosities from a surface near 4,900 K. In 2006 astronomers confirmed a planet orbiting it, Pollux b, a gas giant several times the mass of Jupiter circling the star roughly every 590 days - making Pollux one of the nearest bright stars known to host a planet. Together with Castor it heads the constellation Gemini, the two stars long imagined as the heads of the mythological twins.",
