   "verdict": "Once crowned the largest star. Still ludicrously oversized.",
   "guide": "UY Scuti is a pulsating red supergiant, sometimes classed as a hypergiant, in the constellation Scutum, and for a while it was widely touted as the single largest known star, with a radius estimated near 1,700 times the Sun's - though such measurements carry hefty uncertainty, and the title shuffles between contenders as distances are refined. It sits roughly 5,100 light-years away (the great distance making its size hard to pin down precisely), embedded near the rich star fields of the Milky Way. With a surface around 3,400 K it glows red and is wrapped in shells of gas it has shed as a semiregular variable, its brightness slowly breathing in and out. Plonked at the Sun's position, its surface would swallow the orbit of Jupiter. Like its hypergiant kin, it is destined to end as a supernova.",
