   "objtype": "Eclipsing binary",
   "verdict": "The Demon Star, winking every 2.87 days. Source of a paradox.",
   "guide": "Algol, in Perseus, is the original 'Demon Star' - its name derives from the Arabic for 'the ghoul', and it has long been associated with the head of Medusa that Perseus holds. The reason for its sinister reputation is that, every 2.87 days, Algol abruptly dims by more than a magnitude for several hours before brightening again, an unblinking 'wink' that ancient observers found deeply unnerving. The cause, decoded in the 18th century, is that Algol is the prototype eclipsing binary: a brighter B-type star and a dimmer orange subgiant that periodically pass in front of one another as seen from Earth, about 90 light-years away. It is also famous for the 'Algol paradox' - the less massive star is the more evolved - which forced astronomers to recognise that mass can transfer between close stellar companions.",
   "panic": "DON'T PANIC when the Demon Star winks - it is merely one star eclipsing another, like clockwork every 2.87 days. No ghouls involved. You can watch the whole dimming and recovery in a single evening.",
