   "verdict": "First truly Earth-sized world in a habitable zone.",
   "guide": "Kepler-186f earned its place in the history books in 2014 as the first validated Earth-sized planet found orbiting within the habitable zone of another star. Roughly 1.1 times Earth's radius, it circles Kepler-186, a cool red dwarf about 580 light-years off in Cygnus, every 130 days near the outer edge of the temperate zone, where its star delivers only about a third of the sunlight Earth enjoys. Noon there would feel like a dim, ruddy late afternoon. Whether it actually holds water depends on an atmosphere we cannot yet measure at this distance. It is the outermost of five known planets in the system, the inner four being too hot for comfort. For the milestone-minded hitchhiker, this is where 'Earth-sized and possibly temperate' first stopped being a hypothetical.",
