   "id": "51-pegasi-b",
   "name": "51 Pegasi b (Dimidium)",
   "category": "exoplanet",
   "objtype": "Hot Jupiter",
   "verdict": "The planet that broke the dam: first around a Sun-like star.",
   "guide": "51 Pegasi b, officially named Dimidium, is the planet that started it all, the first exoplanet ever found orbiting an ordinary Sun-like star, announced by Michel Mayor and Didier Queloz in October 1995 (a discovery that later bagged them a Nobel Prize). It promptly broke everyone's assumptions by being a 'hot Jupiter': a gas giant of about half Jupiter's mass scorching around its G-type star every 4.2 days at a blistering 0.05 AU, far closer than Mercury. Nobody had expected a Jovian world to huddle so absurdly close to its sun, and the find forced theorists to invent planetary migration on the spot. Lying about 50 light-years away in Pegasus, Dimidium is a roasted, puffed-up ball of gas with no surface to speak of, but as the world that proved other solar systems exist, it is hallowed ground.",
