   "objtype": "Transiting hot Jupiter",
   "verdict": "First to transit; caught dramatically evaporating into space.",
   "guide": "HD 209458 b, nicknamed Osiris, is the overachiever of early exoplanet science: in 1999 it became the first exoplanet observed transiting its star, letting astronomers measure a planet's size by watching it dim its sun. It then kept collecting firsts, becoming the first exoplanet with a detected atmosphere (2001), complete with sodium, and the first caught actively boiling away, its puffy hydrogen envelope streaming off into a comet-like tail. A hot Jupiter of about 0.69 Jupiter masses, it orbits a Sun-like star every 3.5 days at 0.047 AU, roasting at well over 1,000 K. Located roughly 159 light-years away in Pegasus, Osiris has been the workhorse on which an entire toolkit of atmospheric techniques was first sharpened. It is, in short, the lab rat that taught us how to weigh and sniff alien air.",
