   "verdict": "Cobalt-blue world raining molten glass at hurricane speeds.",
   "guide": "HD 189733 b is what you get when nature designs a planet specifically to ruin your day. This hot Jupiter, about 1.13 Jupiter masses, orbits a K-type star every 2.2 days at 0.031 AU, only 64.5 light-years away in Vulpecula. In 2013 astronomers determined its true colour, a deep azure blue, which sounds lovely until you learn the blue likely comes from silicate clouds, meaning the 'rain' is probably droplets of molten glass. Worse, those droplets are flung sideways by winds clocked at up to 8,700 km/h, roughly seven times the speed of sound, in a permanent dayside temperature topping 1,000 C. It was also the first exoplanet to have a thermal map and detections of water, methane and carbon dioxide in its atmosphere. A genuinely gorgeous, genuinely lethal little world.",
