   "guide": "TOI-700 d holds the distinction of being the first Earth-sized planet found in the habitable zone by NASA's TESS mission, announced in January 2020. Roughly 1.07 Earth radii, it orbits a small, quiet red dwarf about 101 light-years away in Dorado every 37 days, receiving about 86% of Earth's sunlight. Crucially, its host star is unusually calm for an M dwarf, showing little flare activity over a year of monitoring, which makes the planet a more promising candidate for retaining an atmosphere than the average red-dwarf world. The system later gained a planet e, also potentially temperate. TOI-700 d is tidally locked, so climate models picture it with a permanent dayside and nightside, but at least the neighbourhood is unusually peaceful by red-dwarf standards.",
