   "guide": "LHS 1140 b is the sober, sensible choice on this list: a dense super-Earth about 1.7 Earth radii and 5.6 Earth masses, orbiting a quiet red dwarf roughly 49 light-years away in Cetus. Its high density points to a substantial rocky or iron-rich body, and recent work suggests it may even be a water world, possibly hosting a liquid ocean on its dayside. It transits its star every 24.7 days within the habitable zone, receiving about 40% of Earth's sunlight. Because the host is relatively inactive and the planet transits a bright, nearby star, it has become one of the most prized targets for atmospheric study with JWST, which has been gingerly testing whether it holds onto any air. If you are shopping for a rocky world that might actually have kept its atmosphere, this is the showroom model.",
