   "verdict": "Watery sub-Neptune with a hotly contested whiff of biology.",
   "guide": "K2-18 b is the planet that keeps making headlines and then making astronomers argue. A sub-Neptune of about 2.6 Earth radii and 8.6 Earth masses, it orbits a red dwarf around 124 light-years away in Leo, sitting within the habitable zone. In 2019 it became the first habitable-zone planet with detected water vapour. Then in 2023-2025 JWST stirred the pot by detecting carbon-bearing molecules and a tentative, much-debated signal of dimethyl sulphide (DMS), a gas produced on Earth chiefly by life. This fuelled the 'hycean world' hypothesis, an ocean beneath a hydrogen atmosphere. Many scientists remain firmly unconvinced, noting the DMS signal is statistically shaky and could have non-biological explanations. So treat any breathless 'aliens found' rumours with the scepticism of a seasoned hitchhiker.",
