   "guide": "WASP-12b is a planet being devoured, slowly and ungraciously, by its own star. This ultra-hot Jupiter, about 1.4 Jupiter masses, orbits so suicidally close, just 0.023 AU, that it completes a year in barely 26 hours, and the star's gravity has stretched it into an egg shape while siphoning off its atmosphere. Its dayside roasts at around 2,500 K, hot enough that the planet absorbs at least 94% of the light hitting it, making it one of the darkest known worlds, blacker than fresh asphalt. Lying roughly 1,400 light-years away in Auriga, it is also spiralling inward, its orbit decaying so measurably that astronomers can watch its doom approaching on human timescales. It is, in essence, a planet on death row, and the execution is already underway.",
