   "id": "psr-b1257-12",
   "name": "PSR B1257+12",
   "category": "exoplanet",
   "objtype": "Millisecond pulsar with planets",
   "verdict": "A dead star's corpse-light hosts the first known exoplanets.",
   "guide": "PSR B1257+12 is where the entire exoplanet story actually began, in the most macabre setting imaginable. In 1992 Aleksander Wolszczan and Dale Frail announced planets orbiting this object, the first confirmed exoplanets ever, three years before 51 Pegasi b. The snag for romantics: the host is a millisecond pulsar, the rapidly spinning, ultra-dense corpse of a supernova, spinning about 161 times per second and bathing its planets in lethal radiation. Astronomers detected the planets by timing minuscule wobbles in the pulsar's metronomic radio beat. At least three planets orbit it, two roughly four Earth masses and one tiny lunar-mass world, named (in some quarters) Draugr, Poltergeist and Phobetor after suitably ghoulish entities. Lying about 2,300 light-years away in Virgo, it is a graveyard, but a historically momentous one.",
