   "guide": "Kepler-16b is reality's answer to Tatooine, the first unambiguously confirmed circumbinary planet, orbiting not one star but two. Announced in 2011, this Saturn-mass gas giant (about 0.33 Jupiter masses, 0.75 Jupiter radii) circles a pair of stars, a K-dwarf and a small red dwarf, that themselves orbit each other every 41 days. The planet loops around both every 229 days at about 0.7 AU, meaning an observer on a hypothetical moon would genuinely witness double sunsets, just as a certain moisture farmer once moodily watched. It lies roughly 245 light-years away in Cygnus. Being a cold gas giant rather than a desert world, it is rather less hospitable to whining about going to Tosche Station, but as proof that double-sun skies are real, it is the genuine article.",
