   "guide": "GJ 1214 b was the poster child for a whole new class of planet: the mini-Neptune, or possibly a 'water world'. Discovered in 2009 around a red dwarf just 48 light-years away in Ophiuchus, it is about 2.7 Earth radii and 6.5 Earth masses, with a density low enough to suggest a hefty envelope of either thick steam or hydrogen-rich gas over a possible water-rich interior. It orbits its dim star every 1.6 days at a toasty 0.014 AU, so any water would be in exotic high-pressure or supercritical forms rather than pleasant lakes. For years its atmosphere stubbornly hid behind a flat, featureless haze that defeated every telescope, until JWST finally peered through and found a reflective, metal-rich, likely steamy atmosphere. A fascinating in-between world with no Solar System equivalent.",
