   "guide": "Kepler-22b earned its footnote in 2011 as the first confirmed planet found in the habitable zone of a Sun-like star. It orbits Kepler-22, a star slightly cooler and smaller than the Sun, every 290 days, comfortably within the temperate band where its equilibrium temperature could be a balmy 22 C or so given a suitable atmosphere. The hitch is its size: at about 2.4 Earth radii it is too large to confidently call rocky, and may well be a water world or a small Neptune-like body rather than a solid surface you could stroll across. Its mass remains poorly pinned down. Lying roughly 640 light-years away in Cygnus, it is far beyond reach, but as the first 'Goldilocks zone, Sun-like star' planet, it was a genuine landmark on the road to finding another Earth.",
