   "category": "galactic-structure",
   "objtype": "Barred spiral galaxy (SBbc)",
   "verdict": "Your local galaxy. Cosy, if you like crowds of 100 billion.",
   "guide": "Home. Or at least the building you happen to live in, all 100,000 light-years of it. The Milky Way is a barred spiral of type SBbc, a flattened disc of perhaps 100 to 400 billion stars wound into graceful arms, with a fat central bulge and a bar running through its middle like the world's least useful furniture. Its total mass, including the dark stuff nobody can see and everybody argues about, comes to something like 1.5 trillion Suns. The whole apparatus rotates with stately indifference, and you are riding it right now at roughly 220 kilometres per second without spilling your drink. The annoying thing about living inside a galaxy is that you can never get far enough away to photograph it properly, which is why every picture you have ever seen of 'the Milky Way' is, technically, an educated guess.",
