   "id": "sagittarius-a-star",
   "name": "Sagittarius A*",
   "category": "galactic-structure",
   "objtype": "Supermassive black hole",
   "verdict": "The galaxy's drain. 4.3 million Suns down a hole 26,000 ly away.",
   "guide": "At the very centre of everything sits Sagittarius A* (pronounced 'Sagittarius A-star', because astronomers enjoy watching you trip over it), a supermassive black hole weighing about 4.3 million times the mass of the Sun, crammed into a region smaller than the orbit of Mercury. Its existence was proven the hard way, by watching stars whip around an invisible point at thousands of kilometres per second over decades, work that earned a Nobel Prize in 2020. In May 2022 the Event Horizon Telescope released an actual image of it, a fuzzy orange doughnut that is, reassuringly, exactly the size general relativity ordered. It lies some 26,000 light-years away toward the constellation Sagittarius, which is comfortingly far for something with the table manners of a black hole.",
   "panic": "Don't panic: at 26,000 light-years it cannot reach out and tidy you away. Black holes only eat things that fall in, and you are spectacularly bad at falling that far.",
