   "category": "galactic-structure",
   "objtype": "Galactic nucleus / central bulge",
   "verdict": "Downtown: dense, ancient, and best admired from 26,000 ly off.",
   "guide": "The Galactic Centre is the crowded old quarter of the Milky Way, a dense bulge of mostly elderly red and yellow stars packed thousands of times more tightly than the leisurely suburbs where the Sun loafs about. It lies roughly 26,000 light-years away in the direction of the constellation Sagittarius, and you cannot see it in ordinary light because some 30 magnitudes of interstellar dust are standing rudely in the way; you need infrared, radio or X-ray eyes to peer through. At its heart broods the supermassive black hole Sagittarius A*, ringed by a swirling nuclear star cluster and a torus of gas. It is the gravitational pivot about which the entire pinwheel turns, the still-ish point of the spinning galaxy, give or take a few million stars elbowing for room.",
