   "name": "The Galactic Bar",
   "category": "galactic-structure",
   "objtype": "Central stellar bar",
   "verdict": "A 27,000-ly girder of stars that funnels gas inward.",
   "guide": "For decades the Milky Way was filed under 'ordinary spiral' until astronomers noticed it had been hiding a great straight beam of stars running through its middle, like a galaxy that forgot to take off its bandolier. This is the Galactic Bar: an elongated bar-shaped concentration of mostly old stars, roughly 27,000 light-years long, tilted about 27 degrees to our line of sight toward the centre. Bars are gravitational traffic engineers; their non-circular pull torques interstellar gas, robbing it of angular momentum and funnelling it inward to feed the central bulge, the nuclear star formation, and ultimately the black hole's occasional snacks. Infrared star counts from surveys such as COBE and Spitzer nailed the bar's shape. About two-thirds of spiral galaxies sport one, so we are, disappointingly, rather typical.",
