   "category": "galactic-structure",
   "objtype": "Minor spiral arm (spur)",
   "verdict": "Our cul-de-sac. A minor spur the Sun calls home.",
   "guide": "Mostly Harmless, and rather suburban. The Orion Arm, also called the Orion Spur or Local Arm, is the modest minor arm in which the Sun and therefore you currently reside. It is not one of the grand sweeping major arms but a smaller structure wedged between the Sagittarius Arm inward and the Perseus Arm outward, roughly 3,500 light-years across and perhaps 10,000-20,000 light-years long. The Sun sits near its inner edge, around 26,000 light-years from the Galactic Centre. It takes its name from the Orion Nebula and the associated bright stars of Orion, which lie along its length and are some of the few bits of our own arm we can actually point at. Recent radio surveys hint the 'spur' may be grander than its lowly billing suggests.",
   "panic": "Don't panic about living in a minor arm: minor is good. The quiet neighbourhoods have fewer exploding stars and far better views of Orion.",
