   "guide": "When astronomers finally sobered up and counted, they decided the Milky Way has just two dominant major arms rich in old stars: the Perseus Arm and the Scutum-Centaurus Arm. The latter is a grand arm that wraps most of the way around the galaxy, named for the constellations Scutum and Centaurus along which it appears from Earth. Spitzer's infrared star counts in 2008 demoted the Sagittarius and Orion arms to minor status and crowned this one and Perseus as the genuine articles, the two arms that the bar's ends feed into. It harbours dense knots of star formation, including some of the galaxy's most prolific stellar nurseries. So the next time someone calls the Milky Way a 'four-armed spiral', you may raise a knowing eyebrow.",
