   "objtype": "Interstellar superbubble (low-density cavity)",
   "verdict": "A 1,000-ly hole blown by dead stars. We live in the gap.",
   "guide": "The Sun, it turns out, lives in a hole. The Local Bubble is a cavity in the interstellar medium roughly 1,000 light-years across, where the gas is unusually hot, around a million kelvin, and unusually thin, far emptier than the galaxy's average. It was excavated not by anything friendly but by a chain of supernova explosions beginning about 14 million years ago, the death throes of massive stars whose surviving siblings drifted off into the Scorpius-Centaurus and Pleiades associations. The expanding shell of debris swept up gas at its edges, and 2022 mapping showed that nearly all young nearby stars sit on that bubble's surface, born from the very wreckage. The Sun merely wandered in some five to ten million years ago, an uninvited guest in a room demolished long before it arrived.",
