   "objtype": "Interstellar cloud (Local Fluff)",
   "verdict": "The 'Local Fluff' the Sun is drifting through right now.",
   "guide": "Within the great emptiness of the Local Bubble drifts a wisp of slightly denser gas charmingly nicknamed the Local Fluff, more formally the Local Interstellar Cloud. It is about 30 light-years across, warm at roughly 7,000 kelvin, yet still preposterously tenuous, around 0.3 atoms per cubic centimetre, which would qualify as a magnificent vacuum in any earthly laboratory. The Sun entered this cloud somewhere between 44,000 and 150,000 years ago and is sailing through it at about 25 kilometres per second; in a few thousand more it will likely exit into a neighbouring cloud. The Fluff helps inflate the heliosphere, the Sun's protective magnetic bubble, against which Voyager 1 and 2 have already crossed in 2012 and 2018. It is, in short, the actual weather of our local interstellar climate.",
