   "objtype": "Ring of young stars / star-forming regions",
   "verdict": "A tilted ring of hot young stars wrapped around us.",
   "guide": "Gould's Belt is a great ring of bright, hot, young stars and star-forming clouds roughly 3,000 light-years across, tilted about 16 to 20 degrees to the plane of the Milky Way, with the Sun sitting somewhat off to one side of its interior. Named for Benjamin Gould, who described it in 1879, it strings together luminous OB associations and nebulae including those in Orion, Scorpius-Centaurus and the Taurus clouds, and it explains why so many brilliant young stars seem to lie along a band cocked at an angle to the Milky Way's faint stripe. Recent work suggests this 'belt' may be part of a far larger undulating structure, the Radcliffe Wave, a 9,000-light-year sinuous filament of gas discovered in 2020 that the old belt was only ever glimpsing in part.",
