   "objtype": "Gamma-ray lobes (outflow structures)",
   "verdict": "Two 25,000-ly gamma-ray balloons the black hole burped out.",
   "guide": "In 2010, astronomers sifting data from NASA's Fermi Gamma-ray Space Telescope found something enormous that nobody had noticed: two colossal lobes of gamma-ray-emitting gas ballooning above and below the Galactic Centre, each reaching roughly 25,000 light-years from the plane, so the pair spans about 50,000 light-years tip to tip, fully half the width of the galaxy. The Fermi Bubbles are thought to be the fossil belch of the central black hole, Sagittarius A*, or a burst of furious star formation, that detonated several million years ago and is still glowing. Later, the eROSITA X-ray telescope spotted even larger 'eROSITA bubbles' wrapped around them. They are gigantic, energetic, and were sitting in plain sight the whole time, which tells you something humbling about how well we know our own home.",
