   "objtype": "Stellar/dark-matter halo",
   "verdict": "The galaxy's invisible overcoat, mostly dark matter.",
   "guide": "Around and well beyond the bright disc lies the Galactic Halo, a vast roughly spherical region that dwarfs the visible galaxy. It comes in layers: a stellar halo of ancient, metal-poor stars and about 150 known globular clusters scattered like old marbles; a diffuse halo of hot, tenuous gas; and, swamping them all in mass, the dark matter halo, an unseen presence detected only by its gravity that may extend several hundred thousand light-years and contain the overwhelming majority of the galaxy's mass. The halo's stars are some of the oldest things in the galaxy, relics of its violent assembly from devoured dwarf galaxies. If you want to know why the Milky Way's outer rim spins faster than its visible matter should allow, the halo's dark cloak is the leading, if frustratingly invisible, suspect.",
