   "objtype": "Orbital period (concept)",
   "verdict": "One lap of the galaxy: ~230 million years per birthday.",
   "guide": "If you find ordinary birthdays tiresome, consider the Galactic Year, the time it takes the Sun to complete one full orbit around the Galactic Centre: somewhere between 225 and 250 million years, often quoted as about 230 million. The Sun, dragging its planets and you along, sails this enormous loop at roughly 220 kilometres per second, around 26,000 light-years out from the centre. The arithmetic is sobering. The Sun is about 4.6 billion years old, so it has made only about 20 such laps in its entire existence. The dinosaurs went extinct less than one galactic year ago; the whole of recorded human history would not register as a flicker. It is the kind of clock that puts your to-do list firmly in perspective.",
