   "category": "galactic-structure",
   "objtype": "Concept (habitability annulus)",
   "verdict": "The galaxy's nice neighbourhood: not too crowded, not too barren.",
   "guide": "The Galactic Habitable Zone is a Goldilocks idea writ across an entire galaxy: the annular region where conditions might allow complex life to arise and survive. Too close to the centre, and stars are packed tight, supernovae and gamma-ray bursts sterilise everything within reach, and the black hole's neighbourhood is generally hostile. Too far out, and the gas is so metal-poor that there simply aren't enough heavy elements to build rocky planets or, indeed, biochemists. The sweet spot, by one influential 2004 estimate, falls in a band a few thousand light-years wide, and the Sun, at about 26,000 light-years from the centre, sits comfortably within it. The concept is debated, since metallicity and risk vary, but it offers a tidy reason why our quiet galactic suburb may be no accident.",
   "panic": "Don't panic about cosmic real estate: you already live in the desirable annulus, far from the lethal core and well stocked with planet-building elements. Location, as ever, is everything.",
