   "verdict": "The galaxy's premier maternity ward, visible to the naked eye.",
   "guide": "Hang below the three belt stars of Orion and you'll find a fuzzy patch your unaided eye can just about manage from a dark field. That fuzz is M42, the nearest large stellar nursery at roughly 1,344 light-years, a glowing cloud some 24 light-years across busily manufacturing baby stars. At its heart sit four hot young stars called the Trapezium, whose brutal ultraviolet output ionises the surrounding hydrogen and makes the whole thing glow. The official discoverer is usually credited as Nicolas-Claude Fabri de Peiresc in 1610, though it sat in plain sight for all of human history. It is one of the most photographed objects in the sky, which is a polite way of saying every astronomer points their telescope at it the moment they unbox it.",
