   "guide": "Mistaken by countless hopeful stargazers for the Little Dipper, the Pleiades are in fact an open cluster of more than a thousand stars about 444 light-years away in Taurus. The brightest are scorching blue-white B-type stars, blazing through their fuel with the reckless enthusiasm of the young; the whole cluster is a mere 100 million years old or so, practically a toddler by stellar standards. Six or seven shine to the naked eye, hence the Seven Sisters of Greek myth, though sharp eyes under dark skies have counted more. The wispy blue haze around them, once thought to be leftover birth-cloud, is actually an unrelated dust cloud the cluster happens to be drifting through. The Japanese call them Subaru, which is why a certain car badge shows six little stars.",
