   "guide": "That distinctive V of stars marking the face of Taurus the Bull is the Hyades, the closest open star cluster to the Sun at about 153 light-years. Note that bright orange Aldebaran, the bull's angry eye, is a fraud: it sits only 65 light-years away and is simply photobombing the cluster from the foreground, with no actual membership. The genuine Hyades are around 625 million years old, mature enough that their hottest stars have already perished and a few have swollen into red giants. Sharing motion through space with the Pleiades' general neighbourhood but quite distinct, the cluster has been a cornerstone for measuring cosmic distances, since knowing exactly how far away it is helps calibrate the entire distance ladder beyond it.",
