   "guide": "On the 4th of July 1054, Chinese and other astronomers recorded a 'guest star' in Taurus so bright it was visible in daylight for weeks. What they were watching was a massive star detonating, and the Crab Nebula is the still-expanding debris, roughly 6,500 light-years away and growing at around 1,500 kilometres per second. At its centre spins the Crab Pulsar, a neutron star packing more than the Sun's mass into a city-sized sphere, rotating about 30 times every second and sweeping the sky with beams of radiation like a deranged lighthouse. Charles Messier catalogued it first as M1 in 1758, and being annoyed by such fuzzy non-comets is precisely why his famous catalogue exists. The whole thing now spans about 11 light-years.",
