   "guide": "Around 5,700 light-years away in Serpens lies M16, an emission nebula wrapped around a young open cluster of hot stars. Its claim to galactic fame is the Pillars of Creation, towering columns of cold molecular gas and dust several light-years tall, captured by Hubble in 1995 and instantly plastered onto every poster, mug and screensaver in existence. Inside those pillars new stars are condensing, even as the searing ultraviolet light from nearby massive stars slowly evaporates the columns away, a process beautifully described as photoevaporation. There's a poignant twist beloved of dramatic narrators: because the nebula is so distant, the light we see left long ago, so it's entirely possible a nearby supernova has already toppled the pillars and we simply haven't received the news yet.",
