   "verdict": "A dying star's smoke ring, and a glimpse of the Sun's future.",
   "guide": "Tucked between two stars of Lyra's little parallelogram sits M57, a near-perfect luminous doughnut roughly 2,600 light-years away. Despite the misleading name 'planetary nebula', there are no planets involved whatsoever; the term was coined because early observers thought these round glowing blobs resembled planetary discs through their modest telescopes. In reality the Ring is the puffed-off outer atmosphere of a dying Sun-like star, now a hot white dwarf glowing at the centre and lighting up the shell of gas it ejected some thousands of years ago. The ring is expanding at roughly 20-30 kilometres per second. It was discovered in 1779 by Antoine Darquier de Pellepoix, and it offers a sobering preview: in about five billion years, our own Sun will do something rather similar.",
