   "guide": "Far down in the southern sky, around 8,500 light-years away, lies the Carina Nebula, a star-forming region so enormous it dwarfs the more famous Orion Nebula, sprawling over 300 light-years. Lurking within is Eta Carinae, one of the most massive and unstable stars known, a luminous blue variable weighing perhaps 100-150 times the mass of the Sun. In the 1840s it staged the 'Great Eruption', briefly becoming the second-brightest star in the entire sky while ejecting the bipolar Homunculus Nebula now visible around it. Eta Carinae is widely expected to explode as a supernova or hypernova in the astronomically near future, which on a cosmic clock could be tomorrow or a few hundred thousand years hence. The whole region was extensively catalogued by Nicolas-Louis de Lacaille in the 1750s.",
