   "verdict": "A horse-shaped shadow, beloved by photographers and impossible for beginners.",
   "guide": "The Horsehead is one of astronomy's great trickster objects: it is not a glowing cloud at all but a dark nebula, a dense knot of cold dust silhouetted against the bright red emission glow of IC 434 behind it. The chance resemblance to a chess knight or a horse's head has made it a darling of astrophotographers and an absolute nightmare for hopeful visual observers, who often need large telescopes and special filters to glimpse it at all. It lies about 1,500 light-years away in Orion, just south of the belt star Alnitak, and was first recorded on a photographic plate by Williamina Fleming at Harvard in 1888. The 'mane' is slowly eroding under radiation, so this particular horse has perhaps five million years left before its head dissolves.",
