   "verdict": "A dazzlingly intricate planetary nebula, fiendishly complex up close.",
   "guide": "Sitting in Draco at roughly 3,300 light-years, the Cat's Eye is one of the most structurally complex planetary nebulae known, a baffling tangle of concentric shells, knots, jets and arcs that has kept astronomers happily arguing for decades. The leading suspicion is that the central dying star may actually be a binary, whose interactions sculpted the elaborate eye-like patterns. Discovered by William Herschel on the 15th of February 1786, it later earned a place in history as the first planetary nebula whose spectrum was studied, by William Huggins in 1864, proving once and for all that these objects are glowing gas rather than unresolved clusters of stars. The bright inner eye is wrapped in at least eleven faint concentric rings, shells puffed off by the star at intervals of roughly 1,500 years.",
