   "guide": "Omega Centauri is the heavyweight champion of Milky Way globular clusters: roughly 17,000 light-years away, containing on the order of 10 million stars packed into a glittering ball about 150 light-years across, with a total mass near 4 million Suns. So bright it earned a star name, omega Centauri, before anyone realised it was a cluster, it was first noted as non-stellar by Edmond Halley in 1677. Unusually for a globular, its stars show a spread of ages and chemical compositions, which is the smoking gun suggesting it isn't a true globular at all but the stripped-down core of a small dwarf galaxy that the Milky Way devoured long ago. There is even tantalising evidence for an intermediate-mass black hole lurking at its dense centre.",
