   "verdict": "The northern sky's finest globular, and the address we mailed in 1974.",
   "guide": "M13 is the showpiece globular cluster of the northern sky, a tightly bound swarm of several hundred thousand stars about 22,000 light-years away in Hercules, spanning roughly 145 light-years. Edmond Halley discovered it in 1714, and it has been delighting backyard telescopes ever since, resolving into a sparkling sphere of ancient suns around 11-12 billion years old. Its real claim to interstellar fame, however, came in 1974, when the Arecibo radio telescope beamed a 1,679-bit message toward it, a sort of cosmic postcard encoding our numbers, DNA and a stick-figure human. There's a charming flaw in the plan: M13 is so far away the message won't arrive for about 25,000 years, by which time the cluster will have drifted, so we essentially addressed the envelope to where the recipient used to be.",
   "panic": "Don't panic about waiting for a reply to the Arecibo message; at 22,000 light-years, any answer is at least 50,000 years away. Don't hold your breath.",
