   "verdict": "Delicate lace from a star that blew up millennia ago.",
   "guide": "The Veil Nebula is the gossamer wreckage of a supernova that detonated roughly 10,000 to 20,000 years ago, lying about 2,400 light-years away in Cygnus. Part of the larger structure called the Cygnus Loop, it has expanded into an enormous bubble spanning some 3 degrees on the sky, about six full Moons across, broken into delicately filamentary arcs with evocative names like the Witch's Broom and the Eastern Veil. Those wispy threads are actually shock waves, where the still-expanding blast slams into surrounding interstellar gas at over 150 kilometres per second and lights it up. William Herschel discovered portions of it in 1784. Through a telescope with an oxygen-III filter it looks almost unfairly delicate, like cosmic embroidery, which is a remarkable disguise for the violent death of a massive star.",
