   "verdict": "Three nebulae for the price of one, split by dark dust lanes.",
   "guide": "The Trifid is a genuine three-for-one bargain, lying about 4,100 light-years away in Sagittarius near its neighbour the Lagoon Nebula. Its name comes from the way three dark dust lanes appear to divide the glowing nebula into three lobes, the work of dust knots silhouetted against the light. What makes M20 a particular showpiece is that it combines three nebula types at once: a red emission nebula glowing where hot young stars ionise hydrogen, a blue reflection nebula where dust merely scatters starlight, and the dark obscuring dust lanes themselves. Charles Messier discovered it in 1764 and logged it as M20. It is a young, active star-forming region, with newborn stars still embedded in its dense central knot, making it a tidy little textbook of interstellar processes all in one frame.",
   "panic": "Don't panic trying to decide which of the three nebulae to admire; they're all the same object wearing different costumes. Bring a camera, since the colours barely register to the naked eye.",
