   "verdict": "The black hole that cost Stephen Hawking a magazine subscription.",
   "guide": "Discovered as a roaring X-ray source in 1964 and pinned down as a black hole by 1971, Cygnus X-1 is where humanity first said, out loud and with a straight face, 'yes, those exist.' A black hole of roughly 21 solar masses orbits a blue supergiant companion (HDE 226868) every 5.6 days, gnawing stellar wind into a 7-million-Kelvin accretion disc whose X-rays carry across some 7,000 light-years to annoy your instruments. Stephen Hawking famously bet Kip Thorne that it was NOT a black hole, as a tidy insurance policy: if he was wrong about black holes existing, he'd at least win the bet. He lost, and conceded in 1990, paying up with a subscription to Penthouse, much to Mrs Thorne's reported displeasure.",
