   "objtype": "Pulsar (neutron star)",
   "verdict": "The little green men who turned out to be a dead star.",
   "guide": "In 1967, graduate student Jocelyn Bell Burnell spotted an absurdly regular 'bit of scruff' on her chart-recorder data: a radio pulse arriving every 1.337 seconds with clockwork precision. The regularity was so unnatural that the source was half-jokingly labelled LGM-1, for Little Green Men, on the grounds that a metronome that tidy might be somebody trying to phone home. It wasn't aliens; it was the first pulsar ever discovered, a spinning neutron star roughly 1,000 light-years away. The discovery earned a Nobel Prize in 1974, awarded to her supervisor Antony Hewish, which remains one of astronomy's more pointed footnotes. Bell Burnell has since been rather more gracious about it than most of us would manage.",
