   "guide": "Discovered in 2013 by Kevin Luhman trawling NASA's WISE survey, Luhman 16 is the nearest known brown-dwarf binary and, at just 6.5 light-years, the third-closest stellar system to the Sun after the Alpha Centauri group and Barnard's Star. Brown dwarfs are the universe's 'almost-rans': objects too heavy to be planets but too light to ever ignite proper hydrogen fusion and become stars. The pair, an L-type and a T-type dwarf, orbit each other and are cool enough (a few hundred to ~1,300 K) to sport patchy, swirling clouds of mineral dust and condensates. Astronomers have even crudely mapped the weather on the brighter component, making it one of the only objects beyond the Solar System with a recorded forecast: cloudy, with a chance of molten rock.",
