   "guide": "S5-HVS1 is a star in a hurry. Discovered in 2019 by the Southern Stellar Stream Spectroscopic Survey, it is tearing through the galaxy at roughly 1,700 km/s, fast enough to escape the Milky Way entirely. Trace its trajectory backwards and it points straight at Sgr A*, the supermassive black hole at the galactic centre, which it appears to have left around five million years ago. The favoured culprit is the Hills mechanism: a binary star wandered too close to the black hole, one partner was captured, and the other was slingshotted away at preposterous speed, like a cosmic game of crack-the-whip with no survivors invited back. It's an A-type star, currently around 29,000 light-years from us, headed firmly for the exit.",
