   "guide": "Announced in 2022 from ESA's Gaia astrometric data, Gaia BH1 is the closest known black hole to Earth, about 1,560 light-years away in Ophiuchus. What makes it remarkable is how unremarkable it looks: it's a dormant black hole of roughly 10 solar masses, not gulping down gas and therefore not blazing in X-rays like the famous accreting ones. Instead, it was caught by the gravitational wobble it imposes on its companion, an ordinary Sun-like star that orbits the unseen mass every 186 days at a comfortable, un-eaten distance. It is the first such quiet, non-interacting black hole found by watching a star dance around nothing visible, and a hint that the galaxy is quietly littered with millions more, all minding their own business.",
