   "verdict": "A gorgeous cosmic pinwheel once rumoured to be aimed at us.",
   "guide": "WR 104, about 8,000 light-years away in Sagittarius, is a Wolf-Rayet binary that produces one of the most beautiful structures in the galaxy: a glowing 'pinwheel' of dust spiralling out as the colliding stellar winds of a Wolf-Rayet star and an OB companion sweep around their roughly 8-month orbit. Wolf-Rayet stars are massive, furious things shedding their outer layers and barrelling toward a supernova or even a gamma-ray burst. For a while WR 104 had a fearsome reputation, because early imaging hinted its spin axis, along which any future gamma-ray burst would fire, might point close to Earth. Later studies suggested the system is more tilted and less menacing than feared, downgrading it from 'death ray' to merely 'spectacular ornament.'",
