   "guide": "PSR J0740+6620 is a millisecond pulsar that has become a celebrity among physicists for being almost impossibly heavy. At roughly 2.08 solar masses, it sits near the upper limit of how much a neutron star can weigh before collapsing into a black hole, making it one of the most massive neutron stars ever reliably measured. NASA's NICER X-ray telescope mapped hot spots on its surface to pin down its size at about 25 km across, which means it crushes more than two Suns' worth of matter into a sphere the size of a city, an object so dense a teaspoon would weigh billions of tonnes. It spins hundreds of times per second and has a white-dwarf companion. Studying it tells us how matter behaves at densities we can never reproduce in any laboratory.",
