   "verdict": "A nearby pulsar that talks in gamma rays, not radio.",
   "guide": "Geminga is a neutron star about 800 light-years away in Gemini, and one of the closest pulsars to Earth. Its name is a pun: in the Milanese dialect 'gh'e minga' means 'it isn't there,' a wry comment on a gamma-ray source first spotted in 1972 that stubbornly refused to show up at radio wavelengths for nearly two decades. It was finally cracked in 1991-1992 when its 0.237-second pulse was detected in X-rays and gamma rays, revealing it as the prototype of the 'radio-quiet' pulsars, neutron stars whose radio beams happen to miss Earth even though their high-energy beams sweep across us. Being so close, Geminga is a prime suspect for contributing some of the cosmic rays and high-energy particles that constantly rain down on our atmosphere.",
