   "verdict": "A year's worth of the universe's only speed limit.",
   "guide": "Despite the suspiciously time-shaped name, a light-year is a distance: how far light slogs in one Earth year while travelling at its tediously constant 299,792,458 metres per second. Multiply that out and you get roughly 9.46 trillion kilometres, or about 5.88 trillion miles, which is the sort of number that makes hitchhikers stop asking 'are we nearly there yet?' Light is the fastest thing going, so the light-year is also a time machine of sorts: the Andromeda Galaxy is some 2.5 million light-years off, meaning you see it as it looked when your ancestors were still impressed by fire. The nearest star beyond the Sun, Proxima Centauri, sits 4.24 light-years away, which sounds neighbourly until you try walking.",
