   "id": "the-parsec",
   "name": "The Parsec",
   "category": "concept-artifact",
   "objtype": "Unit of distance",
   "verdict": "The astronomer's light-year, and emphatically not a time.",
   "guide": "Astronomers, being a contrary lot, prefer the parsec to the light-year. It equals about 3.26 light-years, or 3.086 trillion kilometres, and is built from geometry rather than glamour: it's the distance at which one astronomical unit subtends one arcsecond of parallax (par-allax-sec-ond, hence par-sec). Hold up a thumb and wink alternate eyes; nearby things shift more. Stars do the same against the background as Earth orbits, and the smaller the shift, the farther the star. The infamous boast about doing 'the Kessel Run in less than twelve parsecs' therefore measures a journey in length, not duration, which has annoyed pedantic hitchhikers for decades. The first stellar parallax was measured by Bessel in 1838, for the star 61 Cygni.",
   "panic": "If someone brags about a fast trip in parsecs, do not correct them mid-blaster-draw. Note the error in your towel's margin and survive.",
