   "verdict": "One Sun-to-here, give or take a planet's wobble.",
   "guide": "The astronomical unit is the cosmos's most parochial ruler: it's essentially the average distance from Earth to the Sun, now fixed by definition at exactly 149,597,870,700 metres. Sunlight, dawdling at its usual brisk pace, takes about 8 minutes and 20 seconds to cover it, which means the Sun you're squinting at is always slightly out of date. The AU is wonderfully handy for measuring the solar system without resorting to silly long numbers: Earth is 1 AU out, Jupiter loiters near 5.2, and Neptune sulks at about 30. Beyond that the unit grows quaint and you graduate to light-years. Historically the AU was fiendishly hard to pin down; Cassini and others triangulated it via Mars in the 1670s, getting impressively close.",
