   "verdict": "Sorting stars by colour, heat, and a cheeky mnemonic.",
   "guide": "Stars come in flavours, and astronomers file them under the letters O, B, A, F, G, K, M, running from scorching blue down to cool red. The order looks like a typo because it is a historical accident, later re-sorted by temperature rather than alphabet. Generations have memorised it via 'Oh Be A Fine Guy/Girl, Kiss Me.' O-types blaze above 30,000 K and burn out fast; M dwarfs idle around 3,000 K and outlast nearly everything. Each class subdivides 0-9, and a Roman numeral gives luminosity, so our own Sun is a thoroughly unremarkable G2V. The system was largely built by Annie Jump Cannon at Harvard in the early 1900s, who classified hundreds of thousands of stars by hand.",
