   "id": "habitable-zone",
   "name": "The Habitable Zone",
   "category": "concept-artifact",
   "objtype": "Orbital region",
   "verdict": "Not too hot, not too cold, statistically rare.",
   "guide": "The habitable zone, fondly nicknamed the Goldilocks zone, is the orbital band around a star where a planet with a sensible atmosphere could keep liquid water on its surface without it boiling off or freezing solid. For our Sun this band runs roughly from 0.95 to 1.7 astronomical units, depending on whose assumptions you trust; Earth sits comfortably inside it, while Venus broils just inward and Mars shivers just out. Cooler stars have their zones huddled in close, which is why red dwarfs keep their potentially habitable worlds on alarmingly short leashes. Being in the zone is necessary but gloriously insufficient: the Moon orbits in it too and remains conspicuously short of oceans, tea, and pleasant weekends. Water is the headline because life as we know it insists on it.",
   "panic": "Don't assume 'habitable zone' means 'hospitable.' Pack water, an atmosphere check, and a healthy scepticism. And a towel.",
