   "id": "drake-equation",
   "name": "The Drake Equation",
   "category": "concept-artifact",
   "objtype": "Probability estimate",
   "verdict": "Multiply seven guesses, get one enormous shrug.",
   "guide": "In 1961 astronomer Frank Drake scribbled an equation to organise a conversation rather than to answer it: N = R* x fp x ne x fl x fi x fc x L. In plain Galactic, the number of communicating civilisations in the Milky Way equals the rate of suitable star formation, times the fraction with planets, times habitable planets per system, times the fraction where life starts, then intelligent life, then communicative technology, all multiplied by how long such a civilisation keeps broadcasting. The cruel beauty is that several terms are barely known, so plugging in optimism gives thousands and plugging in gloom gives roughly one (hello). It isn't a formula so much as a tidy way of admitting how much we don't know. Drake first deployed it at the Green Bank meeting that effectively founded SETI.",
   "panic": "Don't bet your passage on the answer. Treat the galaxy as possibly crowded and possibly empty, and behave politely in both cases.",
