   "objtype": "Interstellar space probe",
   "verdict": "Humanity's farthest hand, still waving from the dark.",
   "guide": "Launched on 5 September 1977, Voyager 1 is the most distant human-made object ever, currently around 25 to 26 billion kilometres out (about 167 AU and climbing) and racing toward becoming the first artefact a full light-day from Earth in November 2026. After flybys of Jupiter in 1979 and Saturn in 1980, it skipped further sightseeing for a faster escape, and on 25 August 2012 it crossed the heliopause into interstellar space, the first spacecraft to do so. It carries the Golden Record and a still-functioning radio whose feeble signal now takes roughly a full day to reach us. Powered by a slowly fading plutonium generator, it sends data at a trickle while drifting toward, eventually, the general direction of the constellation Camelopardalis over tens of thousands of years.",
