   "id": "voyager-2",
   "name": "Voyager 2",
   "category": "concept-artifact",
   "objtype": "Interstellar space probe",
   "verdict": "The only craft to greet all four giants in person.",
   "guide": "Confusingly, Voyager 2 launched FIRST, on 20 August 1977, a fortnight before its sibling. It took the scenic route, becoming the only spacecraft to visit all four giant planets: Jupiter (1979), Saturn (1981), Uranus (1986), and Neptune (1989), riding a rare planetary alignment that won't recur for over a century. On 5 November 2018 it followed Voyager 1 across the heliopause into interstellar space, giving scientists a second, differently angled measurement of the boundary. Now over 140 AU from the Sun and travelling a little under 16 km/s, it too carries a Golden Record and a dwindling plutonium power supply that engineers nurse along by switching off instruments one by one. It heads roughly toward the southern constellation Pavo, where in about 40,000 years it will pass a distant star with magnificent indifference.",
