   "id": "pioneer-plaque",
   "name": "The Pioneer Plaque",
   "category": "concept-artifact",
   "objtype": "Interstellar message",
   "verdict": "Earth's first cosmic business card, etched in gold.",
   "guide": "Bolted to Pioneer 10 (launched 1972) and its twin Pioneer 11 (1973) are matching gold-anodised aluminium plaques, humanity's first attempt to post a return address into the void. Designed by Carl Sagan and Frank Drake, with the figures drawn by Linda Salzman Sagan, each 15-by-23-centimetre plate shows a nude man and woman, the man's hand raised in greeting, beside a diagram of our solar system marking which planet the craft departed. The clever bit is the navigation chart: a starburst of lines giving the directions and periods of 14 pulsars relative to the Sun, plus the galactic centre, a cosmic GPS encoded in the steady ticking of dead stars. The whole message is keyed to the hyperfine transition of hydrogen, the one ruler any technological species should recognise.",
